package com.jamescornwell.setsee;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Collections;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class OverlayTest
{
	private final Client client = mock(Client.class);
	private final Widget container = mock(Widget.class);
	private final Widget child = mock(Widget.class);
	private final SetSeeConfig config = mock(SetSeeConfig.class);
	private final TooltipManager tooltips = mock(TooltipManager.class);
	private final SetSeeState state = new SetSeeState();
	private SetSeeOverlay overlay;

	@Before
	public void setup()
	{
		SetRecipe recipe = new CacheFixture().recipe(13024);
		state.snapshot = new SetSeeState.Snapshot(Collections.singletonList(SetMatcher.match(recipe,
			Collections.singletonMap(recipe.id, 1L), 27, true)));
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getWidget(InterfaceID.Itemsets.ITEMLIST)).thenReturn(container);
		when(client.getMouseCanvasPosition()).thenReturn(new Point(-1, -1));
		when(container.getBounds()).thenReturn(new Rectangle(20, 20, 80, 50));
		when(container.getDynamicChildren()).thenReturn(new Widget[]{child});
		when(child.getItemId()).thenReturn(recipe.id);
		when(child.getBounds()).thenReturn(new Rectangle(25, 10, 36, 32));
		when(config.showLabels()).thenReturn(true);
		when(config.showTooltips()).thenReturn(true);
		overlay = new SetSeeOverlay(client, config, state, tooltips);
	}

	private BufferedImage render()
	{
		BufferedImage image = new BufferedImage(150, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			overlay.render(g);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	@Test
	public void partiallyScrolledItemIsClippedToViewport()
	{
		BufferedImage image = render();
		assertEquals(0, image.getRGB(26, 11));
		assertNotEquals(0, image.getRGB(26, 25));
	}

	@Test
	public void movedWidgetUsesItsNewBounds()
	{
		when(child.getBounds()).thenReturn(new Rectangle(50, 35, 36, 32));
		BufferedImage image = render();
		assertEquals(0, image.getRGB(26, 25));
		assertNotEquals(0, image.getRGB(51, 40));
	}

	@Test
	public void nativeFilterHiddenItemsAreNotDrawn()
	{
		when(child.isHidden()).thenReturn(true);
		assertEquals(0, render().getRGB(26, 25));
	}

	@Test
	public void closedWindowDoesNotDrawEvenIfSnapshotStillExists()
	{
		when(container.isHidden()).thenReturn(true);
		assertEquals(0, render().getRGB(26, 25));
	}

	@Test
	public void tooltipOnlyTriggersInsideVisiblePartOfItem()
	{
		when(client.getMouseCanvasPosition()).thenReturn(new Point(30, 12));
		render();
		verify(tooltips, never()).add(any(Tooltip.class));
		when(client.getMouseCanvasPosition()).thenReturn(new Point(30, 25));
		render();
		verify(tooltips).add(any(Tooltip.class));
	}

	@Test
	public void contextMenuSuppressesTooltips()
	{
		when(client.getMouseCanvasPosition()).thenReturn(new Point(30, 25));
		when(client.isMenuOpen()).thenReturn(true);
		render();
		verify(tooltips, never()).add(any(Tooltip.class));
	}
}

package com.jamescornwell.setsee;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

final class CacheFixture
{
	final Map<Integer, Map<Integer, Integer>> enums = new HashMap<>();
	final Map<Integer, CatalogueLoader.ItemDetails> items = new HashMap<>();
	final List<SetRecipe> recipes;

	CacheFixture()
	{
		try (InputStreamReader reader = new InputStreamReader(
			CacheFixture.class.getResourceAsStream("/catalogue-snapshot.json"), StandardCharsets.UTF_8))
		{
			JsonObject data = new Gson().fromJson(reader, JsonObject.class);
			for (Map.Entry<String, JsonElement> entry : data.getAsJsonObject("enums").entrySet())
			{
				Map<Integer, Integer> values = new HashMap<>();
				for (Map.Entry<String, JsonElement> value : entry.getValue().getAsJsonObject().entrySet())
				{
					values.put(Integer.parseInt(value.getKey()), value.getValue().getAsInt());
				}
				enums.put(Integer.parseInt(entry.getKey()), values);
			}
			for (JsonElement element : data.getAsJsonArray("items"))
			{
				JsonObject item = element.getAsJsonObject();
				int id = item.get("id").getAsInt();
				items.put(id, new CatalogueLoader.ItemDetails(id, item.get("note").getAsInt(),
					item.get("name").getAsString(), item.get("stackable").getAsBoolean(), item.get("members").getAsBoolean()));
			}
		}
		catch (Exception ex)
		{
			throw new AssertionError("Cannot load the audited cache fixture", ex);
		}
		recipes = CatalogueLoader.load(enums::get, items::get);
	}

	SetRecipe recipe(int id)
	{
		return recipes.stream().filter(r -> r.id == id).findFirst().orElseThrow(AssertionError::new);
	}

	static Map<Integer, Long> components(SetRecipe recipe, boolean noted, long copies)
	{
		Map<Integer, Long> values = new HashMap<>();
		for (SetRecipe.Component c : recipe.components)
		{
			values.put(noted ? c.notedOrSelf() : c.id, copies * c.quantity);
		}
		return values;
	}
}

package com.jamescornwell.setsee;

import java.util.ArrayDeque;
import java.util.EnumSet;
import java.util.Map;
import java.util.Queue;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class LifecycleTest
{
	private final CacheFixture f = new CacheFixture();
	private final Queue<Runnable> queued = new ArrayDeque<>();
	private final Client client = mock(Client.class);
	private final Widget list = mock(Widget.class);
	private final ItemContainer inventory = mock(ItemContainer.class);
	private SetSeePlugin plugin;
	private boolean onClientThread;

	@Before
	public void setup()
	{
		plugin = new SetSeePlugin();
		plugin.client = client;
		plugin.clientThread = mock(ClientThread.class);
		plugin.overlayManager = mock(OverlayManager.class);
		plugin.state = new SetSeeState();
		plugin.overlay = new SetSeeOverlay(client, mock(SetSeeConfig.class),
			plugin.state, mock(TooltipManager.class));
		doAnswer(invocation -> { queued.add(invocation.getArgument(0)); return null; })
			.when(plugin.clientThread).invokeLater(any(Runnable.class));
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getWidget(InterfaceID.Itemsets.ITEMLIST)).thenReturn(list);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		when(inventory.getItems()).thenReturn(new Item[]{new Item(13024, 1)});
		when(client.getEnum(anyInt())).thenAnswer(invocation ->
		{
			assertTrue("Game data was accessed off the client thread", onClientThread);
			Map<Integer, Integer> data = f.enums.get(invocation.<Integer>getArgument(0));
			EnumComposition definition = mock(EnumComposition.class);
			int[] keys = data.keySet().stream().mapToInt(Integer::intValue).toArray();
			when(definition.getKeys()).thenReturn(keys);
			when(definition.getIntVals()).thenReturn(java.util.Arrays.stream(keys).map(data::get).toArray());
			return definition;
		});
		when(client.getItemDefinition(anyInt())).thenAnswer(invocation ->
		{
			CatalogueLoader.ItemDetails item = f.items.get(invocation.<Integer>getArgument(0));
			ItemComposition definition = mock(ItemComposition.class);
			when(definition.getName()).thenReturn(item.name);
			when(definition.getLinkedNoteId()).thenReturn(item.noteId);
			when(definition.isMembers()).thenReturn(item.members);
			when(definition.isStackable()).thenReturn(item.stackable);
			return definition;
		});
	}

	private void drain()
	{
		onClientThread = true;
		while (!queued.isEmpty())
		{
			queued.remove().run();
		}
	}

	@Test
	public void enablingFromSwingWaitsForClientThread() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> plugin.startUp());
		verify(client, never()).getEnum(anyInt());
		drain();
		assertEquals(1, plugin.state.snapshot.boxes.get(13024).boxes);
	}

	@Test
	public void queuedStartupCannotRestoreStateAfterDisable() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> plugin.startUp());
		SwingUtilities.invokeAndWait(() -> plugin.shutDown());
		drain();
		assertTrue(plugin.state.snapshot.boxes.isEmpty());
		verify(client, never()).getEnum(anyInt());
	}

	@Test
	public void quickDisableReenableIgnoresFirstSession() throws Exception
	{
		SwingUtilities.invokeAndWait(() -> plugin.startUp());
		SwingUtilities.invokeAndWait(() -> plugin.shutDown());
		SwingUtilities.invokeAndWait(() -> plugin.startUp());
		drain();
		assertEquals(1, plugin.state.snapshot.boxes.get(13024).boxes);
		verify(client, times(1)).getEnum(CatalogueLoader.SET_LIST);
	}

	@Test
	public void closingTheWindowImmediatelyClearsState()
	{
		plugin.startUp();
		drain();
		when(list.isHidden()).thenReturn(true);
		plugin.onClientTick(null);
		assertTrue(plugin.state.snapshot.boxes.isEmpty());
	}

	@Test
	public void inventoryChangeUpdatesWithoutWaitingForGameTick()
	{
		plugin.startUp();
		drain();
		when(inventory.getItems()).thenReturn(new Item[]{new Item(1127, 1)});
		ItemContainerChanged event = new ItemContainerChanged(InventoryID.INV, inventory);
		plugin.onItemContainerChanged(event);
		plugin.onClientTick(null);
		assertEquals(0, plugin.state.snapshot.boxes.get(13024).boxes);
		assertTrue(plugin.state.snapshot.boxes.get(13024).incomplete());
	}

	@Test
	public void missingInventoryIsRetriedWithoutCrash()
	{
		when(client.getItemContainer(InventoryID.INV)).thenReturn(null);
		plugin.startUp();
		drain();
		assertTrue(plugin.state.snapshot.boxes.isEmpty());
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		plugin.onClientTick(null);
		assertEquals(1, plugin.state.snapshot.boxes.get(13024).boxes);
	}

	@Test
	public void loadingClearsStateAndLoginCanRefreshAgain()
	{
		plugin.startUp();
		drain();
		GameStateChanged event = mock(GameStateChanged.class);
		when(event.getGameState()).thenReturn(GameState.LOADING);
		when(client.getGameState()).thenReturn(GameState.LOADING);
		plugin.onGameStateChanged(event);
		assertTrue(plugin.state.snapshot.boxes.isEmpty());
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		plugin.onClientTick(null);
		assertEquals(1, plugin.state.snapshot.boxes.get(13024).boxes);
	}

	@Test
	public void corruptCatalogueFailsClosedInsteadOfPartialHighlights()
	{
		f.enums.get(CatalogueLoader.SET_LOOKUP).remove(13024);
		plugin.startUp();
		drain();
		assertTrue(plugin.state.snapshot.boxes.isEmpty());
		plugin.onClientTick(null);
		assertTrue(plugin.state.snapshot.boxes.isEmpty());
	}
}

package com.jamescornwell.setsee;

import java.util.Collection;
import java.util.Collections;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;
import static org.junit.Assume.assumeTrue;

@RunWith(Parameterized.class)
public class EveryRecipeTest
{
	@Parameterized.Parameters(name = "{0}")
	public static Collection<Object[]> data()
	{
		return new CacheFixture().recipes.stream().map(r -> new Object[]{r.name, r}).collect(Collectors.toList());
	}

	private final SetRecipe recipe;

	public EveryRecipeTest(String name, SetRecipe recipe)
	{
		this.recipe = recipe;
	}

	@Test
	public void unnotedComponentsPack()
	{
		assertEquals(3, SetMatcher.match(recipe, CacheFixture.components(recipe, false, 3), 0, true).packCount);
	}

	@Test
	public void notedComponentsPackWithoutDoubleCountingStackablePages()
	{
		assertEquals(7, SetMatcher.match(recipe, CacheFixture.components(recipe, true, 7), 0, true).packCount);
	}

	@Test
	public void eachMissingComponentPreventsPacking()
	{
		for (SetRecipe.Component c : recipe.components)
		{
			Map<Integer, Long> counts = CacheFixture.components(recipe, false, 1);
			counts.remove(c.id);
			SetMatcher.Status status = SetMatcher.match(recipe, counts, 20, true);
			assertEquals(c.name, 0, status.packCount);
			assertTrue(c.name, status.missing(false).containsKey(c.name));
		}
	}

	@Test
	public void mixedFormsDoNotPack()
	{
		assumeTrue(recipe.components.stream().filter(c -> c.noteId > 0).count() >= 2);
		Map<Integer, Long> counts = CacheFixture.components(recipe, false, 1);
		SetRecipe.Component c = recipe.components.get(0);
		counts.remove(c.id);
		counts.put(c.noteId, (long) c.quantity);
		SetMatcher.Status status = SetMatcher.match(recipe, counts, 20, true);
		assertEquals(0, status.packCount);
		assertTrue(status.incomplete());
		assertEquals(recipe.components.size(), status.ownedTypes);
	}

	@Test
	public void bothBoxFormsAreRecognised()
	{
		for (int id : new int[]{recipe.id, recipe.noteId})
		{
			SetMatcher.Status status = SetMatcher.match(recipe, Collections.singletonMap(id, 5L), 20, true);
			assertEquals(5, status.boxes);
			SetSeeState.Snapshot snapshot = new SetSeeState.Snapshot(Collections.singletonList(status));
			assertFalse(SetHighlights.forItem(snapshot, id, false, false).get(0).incomplete);
			assertFalse(SetHighlights.forItem(snapshot, recipe.id, true, false).get(0).incomplete);
		}
	}

	@Test
	public void emptyInventoryNeverHighlights()
	{
		SetMatcher.Status status = SetMatcher.match(recipe, Collections.emptyMap(), 28, true);
		SetSeeState.Snapshot snapshot = new SetSeeState.Snapshot(Collections.singletonList(status));
		assertEquals(0, status.packCount);
		assertFalse(status.incomplete());
		assertTrue(SetHighlights.forItem(snapshot, recipe.id, true, true).isEmpty());
	}

	@Test
	public void completeColoursNeverUseReservedRed()
	{
		float[] hsb = java.awt.Color.RGBtoHSB(SetHighlights.colour(recipe).getRed(),
			SetHighlights.colour(recipe).getGreen(), SetHighlights.colour(recipe).getBlue(), null);
		assertTrue(hsb[0] > 0.12 && hsb[0] < 0.8);
		assertNotEquals(SetHighlights.INCOMPLETE, SetHighlights.colour(recipe));
	}
}

