import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

final class SetSeeOverlay extends Overlay
{
	private static final BasicStroke SOLID = new BasicStroke(2);
	private static final BasicStroke DASHED = new BasicStroke(2, BasicStroke.CAP_BUTT,
		BasicStroke.JOIN_MITER, 10, new float[]{3, 3}, 0);
	private static final Font LABEL_FONT = new Font(Font.MONOSPACED, Font.BOLD, 9);
	private final Client client;
	private final SetSeeConfig config;
	private final SetSeeState state;
	private final TooltipManager tooltips;

	@Inject
	SetSeeOverlay(Client client, SetSeeConfig config, SetSeeState state, TooltipManager tooltips)
	{
		this.client = client;
		this.config = config;
		this.state = state;
		this.tooltips = tooltips;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!SetSeePlugin.windowOpen(client))
		{
			return null;
		}
		SetSeeState.Snapshot snapshot = state.snapshot;
		if (snapshot.boxes.isEmpty())
		{
			return null;
		}
		// Use live widget bounds rather than fixed positions. This follows scrolling,
		// the native craftable filter, stretched mode and movable-interface plugins.
		renderContainer(graphics, client.getWidget(InterfaceID.Itemsets.ITEMLIST), true, snapshot);
		renderContainer(graphics, client.getWidget(InterfaceID.ItemsetsSide.ITEMS), false, snapshot);
		return null;
	}

	private void renderContainer(Graphics2D graphics, Widget container, boolean setWindow, SetSeeState.Snapshot snapshot)
	{
		if (container == null || container.isHidden())
		{
			return;
		}
		Widget[] children = container.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		Rectangle viewport = container.getBounds();
		Point mouse = client.getMouseCanvasPosition();
		for (Widget child : children)
		{
			if (child == null || child.isHidden() || child.getItemId() <= 0)
			{
				continue;
			}
			Rectangle bounds = child.getBounds();
			Rectangle visible = bounds.intersection(viewport);
			if (visible.isEmpty())
			{
				continue;
			}
			int id = child.getItemId();
			List<SetHighlights.Mark> marks = SetHighlights.forItem(snapshot, id, setWindow, config.showIncomplete());
			if (!marks.isEmpty())
			{
				Graphics2D g = (Graphics2D) graphics.create();
				try
				{
					g.clip(viewport);
					drawMarks(g, bounds, marks, config.showLabels());
				}
				finally
				{
					g.dispose();
				}
			}
			if (config.showTooltips() && !client.isMenuOpen() && visible.contains(mouse.getX(), mouse.getY()))
			{
				String text = SetTooltip.forItem(snapshot, id);
				if (!text.isEmpty())
				{
					tooltips.add(new Tooltip(text));
				}
			}
		}
	}

	static void drawMarks(Graphics2D g, Rectangle bounds, List<SetHighlights.Mark> marks, boolean labels)
	{
		if (marks.size() == 1)
		{
			SetHighlights.Mark mark = marks.get(0);
			Color colour = mark.colour();
			g.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), mark.incomplete ? 25 : 35));
			g.fillRect(bounds.x + 1, bounds.y + 1, bounds.width - 2, bounds.height - 2);
			g.setColor(colour);
			g.setStroke(mark.incomplete ? DASHED : SOLID);
			g.drawRect(bounds.x + 1, bounds.y + 1, bounds.width - 3, bounds.height - 3);
		}
		// Shared components get separate coloured chips instead of overwriting one border.
		int shown = Math.min(marks.size(), 2);
		int chipWidth = Math.min(22, (bounds.width - 2) / shown);
		g.setFont(LABEL_FONT);
		for (int i = 0; i < shown; i++)
		{
			SetHighlights.Mark mark = marks.get(i);
			int x = bounds.x + 1 + i * chipWidth;
			int y = bounds.y + bounds.height - (labels ? 11 : 4);
			g.setColor(mark.colour());
			g.fillRect(x, y, chipWidth - 1, labels ? 10 : 3);
			if (labels)
			{
				String label = i == shown - 1 && marks.size() > shown ? "+" + (marks.size() - shown + 1)
					: String.valueOf(mark.recipe.label);
				g.setColor(Color.BLACK);
				g.drawString(label, x + 1, y + 8);
			}
		}
	}
}

package com.jamescornwell.setsee;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;

@Singleton
final class SetSeeState
{
	static final class Snapshot
	{
		static final Snapshot EMPTY = new Snapshot(Collections.emptyList());
		final Map<Integer, SetMatcher.Status> boxes;
		final Map<Integer, List<SetMatcher.Status>> components;

		Snapshot(List<SetMatcher.Status> statuses)
		{
			Map<Integer, SetMatcher.Status> boxIndex = new LinkedHashMap<>();
			Map<Integer, List<SetMatcher.Status>> componentIndex = new LinkedHashMap<>();
			for (SetMatcher.Status status : statuses)
			{
				SetRecipe r = status.recipe;
				boxIndex.put(r.id, status);
				if (r.noteId > 0)
				{
					boxIndex.put(r.noteId, status);
				}
				for (SetRecipe.Component c : r.components)
				{
					componentIndex.computeIfAbsent(c.id, k -> new ArrayList<>()).add(status);
					if (c.noteId > 0)
					{
						componentIndex.computeIfAbsent(c.noteId, k -> new ArrayList<>()).add(status);
					}
				}
			}
			componentIndex.replaceAll((id, values) -> Collections.unmodifiableList(values));
			boxes = Collections.unmodifiableMap(boxIndex);
			components = Collections.unmodifiableMap(componentIndex);
		}
	}

	volatile Snapshot snapshot = Snapshot.EMPTY;
}

package com.jamescornwell.setsee;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.IntFunction;

final class CatalogueLoader
{
	// No named RuneLite enum constants exist for these. Verified in Jagex's
	// itemsets_init / script8020 and itemsets_side_draw client scripts.
	static final int SET_LIST = 1033;
	static final int SET_LOOKUP = 1034;

	static final class ItemDetails
	{
		final int id;
		final int noteId;
		final String name;
		final boolean stackable;
		final boolean members;

		ItemDetails(int id, int noteId, String name, boolean stackable, boolean members)
		{
			this.id = id;
			this.noteId = noteId;
			this.name = name;
			this.stackable = stackable;
			this.members = members;
		}
	}

	static List<SetRecipe> load(IntFunction<Map<Integer, Integer>> enums, IntFunction<ItemDetails> items)
	{
		Map<Integer, Integer> index = enums.apply(SET_LIST);
		Map<Integer, Integer> reverse = enums.apply(SET_LOOKUP);
		if (index == null || reverse == null || index.isEmpty() || reverse.isEmpty())
		{
			throw new IllegalStateException("GE set definitions are unavailable");
		}
		index = new TreeMap<>(index);
		Map<Integer, SetRecipe> recipes = new LinkedHashMap<>();
		Map<Integer, Integer> seenEnums = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> entry : index.entrySet())
		{
			if (entry.getKey() < 0 || entry.getValue() <= 0)
			{
				throw new IllegalStateException("Unexpected GE set index");
			}
			Map<Integer, Integer> definition = enums.apply(entry.getValue());
			if (definition == null)
			{
				throw new IllegalStateException("Missing GE set recipe " + entry.getValue());
			}
			definition = new TreeMap<>(definition);
			Integer boxId = definition.get(-1);
			if (boxId == null || boxId <= 0 || !entry.getValue().equals(reverse.get(boxId)))
			{
				throw new IllegalStateException("GE set index and reverse lookup disagree");
			}
			if (recipes.containsKey(boxId))
			{
				if (!entry.getValue().equals(seenEnums.get(boxId)))
				{
					throw new IllegalStateException("Conflicting GE set recipes");
				}
				continue; // The current game list contains duplicate display entries.
			}
			Map<Integer, Integer> amounts = new LinkedHashMap<>();
			int expectedKey = 0;
			for (Map.Entry<Integer, Integer> component : definition.entrySet())
			{
				if (component.getKey() == -1)
				{
					continue;
				}
				if (component.getKey() != expectedKey++ || component.getValue() <= 0)
				{
					throw new IllegalStateException("Unexpected GE component definition");
				}
				amounts.merge(component.getValue(), 1, Integer::sum);
			}
			if (amounts.isEmpty())
			{
				throw new IllegalStateException("GE set has no components");
			}
			List<SetRecipe.Component> components = new ArrayList<>();
			for (Map.Entry<Integer, Integer> amount : amounts.entrySet())
			{
				ItemDetails item = readItem(items, amount.getKey());
				components.add(new SetRecipe.Component(item.id, item.noteId, item.name, amount.getValue(), item.stackable));
			}
			ItemDetails box = readItem(items, boxId);
			recipes.put(boxId, new SetRecipe(box.id, box.noteId, box.name, recipes.size() + 1, box.members, components));
			seenEnums.put(boxId, entry.getValue());
		}
		if (!recipes.keySet().equals(reverse.keySet()))
		{
			throw new IllegalStateException("GE set catalogue is incomplete");
		}
		return Collections.unmodifiableList(new ArrayList<>(recipes.values()));
	}

	private static ItemDetails readItem(IntFunction<ItemDetails> items, int id)
	{
		ItemDetails item = items.apply(id);
		if (item == null || item.id != id || item.name == null)
		{
			throw new IllegalStateException("Missing GE set item " + id);
		}
		return item;
	}
}

